import React, { useCallback, useEffect, useMemo, useState } from "react";
import { View, Text, Pressable, StyleSheet, ScrollView, Switch, Linking, Modal, Platform, Alert } from "react-native";
import { useRouter, useFocusEffect } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import Animated, { FadeInDown } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { LinearGradient } from "expo-linear-gradient";
import { C, S, R, fmt } from "@/src/lib/theme";
import { api } from "@/src/lib/api";
import { useAuth } from "@/src/lib/auth";
import { isAdminCourierUser } from "@/src/lib/roleRoute";
import { pointUrl, getCurrentLocation } from "@/src/lib/geo";
import zarramarketLogo from "../assets/images/zarramarket-logo.png";

type FinalizeMap = Record<number, "delivered" | "returned">;

const RECEIPT_LOGO_URI = "data:image/png;base64,";
const RECEIPT_SELLER_NAME = "ZarraMarket";

const escapeHtml = (value: any) => String(value ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/\"/g, "&quot;")
  .replace(/'/g, "&#39;");

const orderDateLabel = (value?: string) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("ru-RU");
};

const itemUnitContents = (item: any) => {
  const mode = item.sale_mode || item.unit_type || "piece";
  const upb = Number(item.units_per_box || 0);
  if (mode === "kg" || item.unit_type === "kg") return "1 kg";
  if (mode === "box" && upb > 0) return `${upb} dona`;
  return "1 dona";
};

const itemPiecePrice = (item: any) => {
  const mode = item.sale_mode || item.unit_type || "piece";
  const upb = Number(item.units_per_box || 0);
  const price = Number(item.price || 0);
  if (mode === "box" && upb > 0) return price / upb;
  return price;
};

const receiptRowsHtml = (order: any) => (order.items || []).map((item: any, idx: number) => {
  const qty = Number(item.qty || 0);
  const linePrice = Number(item.price || 0);
  const total = qty * linePrice;
  const contents = itemUnitContents(item);
  const piecePrice = itemPiecePrice(item);
  return `
    <tr>
      <td>${idx + 1}</td>
      <td>${escapeHtml(item.name?.uz || item.name || "Mahsulot")}${item.variation ? ` • ${escapeHtml(item.variation)}` : ""}</td>
      <td>${escapeHtml(fmt(linePrice))}</td>
      <td>${escapeHtml(contents)}</td>
      <td>${escapeHtml(fmt(piecePrice))}</td>
      <td>${qty}</td>
      <td>${escapeHtml(fmt(total))}</td>
    </tr>`;
}).join("");

const buildReceiptHtml = (order: any) => {
  const subtotal = Number(order.subtotal || 0);
  const deliveryFee = Number(order.delivery_fee || 0);
  const discount = Number(order.discount || 0);
  const total = Number(order.total || 0);
  return `<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(order.number || "Chek")}</title>
  <style>
    body { font-family: Arial, Helvetica, sans-serif; background:#f3f4f6; margin:0; padding:24px; color:#111827; }
    .sheet { width: 860px; max-width: 100%; margin: 0 auto; background:#fff; border:1px solid #111; padding:18px 18px 22px; }
    .header-title { text-align:center; font-weight:700; font-size:16px; margin-bottom:10px; }
    .meta-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; font-size:13px; line-height:1.45; margin-bottom:12px; }
    .meta-grid strong { display:inline-block; min-width:88px; }
    table { width:100%; border-collapse:collapse; font-size:12px; }
    th, td { border:1px solid #333; padding:6px 7px; vertical-align:top; }
    th { background:#f3f4f6; text-align:left; }
    td:nth-child(1), td:nth-child(4), td:nth-child(6) { text-align:center; }
    td:nth-child(3), td:nth-child(5), td:nth-child(7) { text-align:right; white-space:nowrap; }
    .summary { margin-top:12px; margin-left:auto; width:320px; font-size:13px; }
    .sum-row { display:flex; justify-content:space-between; padding:4px 0; border-bottom:1px dashed #cbd5e1; }
    .sum-row.total { font-size:16px; font-weight:700; border-bottom:0; padding-top:10px; }
    .footer { display:flex; justify-content:space-between; gap:20px; margin-top:22px; font-size:13px; }
    .sign { flex:1; border-top:1px solid #111; padding-top:8px; }
    .note { font-size:11px; color:#6b7280; margin-top:14px; text-align:center; }
    @media print {
      body { background:#fff; padding:0; }
      .sheet { border:0; width:auto; padding:0; }
    }
  </style>
</head>
<body>
  <div class="sheet">
    <div style="display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:10px;">
      <img src="${RECEIPT_LOGO_URI}" alt="ZarraMarket" style="width:54px;height:54px;object-fit:contain;border-radius:12px;" />
      <div>
        <div class="header-title" style="margin-bottom:2px;">ZarraMarket</div>
        <div style="text-align:center;font-size:12px;color:#4b5563;">Накладная / Чек ${escapeHtml(order.number || "")}</div>
      </div>
    </div>
    <div class="meta-grid">
      <div>
        <div><strong>Дата:</strong> ${escapeHtml(orderDateLabel(order.created_at))}</div>
        <div><strong>Клиент:</strong> ${escapeHtml(order.client_name || "")}</div>
        <div><strong>Тел:</strong> ${escapeHtml(order.client_phone || "")}</div>
        <div><strong>Адрес:</strong> ${escapeHtml(order.address_text || "")}</div>
      </div>
      <div>
        <div><strong>Продавец:</strong> ${escapeHtml(RECEIPT_SELLER_NAME)}</div>
        <div><strong>Оплата:</strong> ${escapeHtml(order.payment_method || "cash")}</div>
        <div><strong>Статус:</strong> Курьерский чек</div>
      </div>
    </div>
    <table>
      <thead>
        <tr>
          <th style="width:36px">№</th>
          <th>Tovar nomi</th>
          <th style="width:100px">1 tovar narxi</th>
          <th style="width:90px">1 tovar ichida</th>
          <th style="width:100px">1 dona/kg narxi</th>
          <th style="width:70px">Jami soni</th>
          <th style="width:110px">Jami summa</th>
        </tr>
      </thead>
      <tbody>${receiptRowsHtml(order)}</tbody>
    </table>
    <div class="summary">
      <div class="sum-row"><span>Товары</span><strong>${escapeHtml(fmt(subtotal))}</strong></div>
      <div class="sum-row"><span>Доставка</span><strong>${escapeHtml(fmt(deliveryFee))}</strong></div>
      <div class="sum-row"><span>Скидка</span><strong>${escapeHtml(fmt(discount))}</strong></div>
      <div class="sum-row total"><span>Итого</span><strong>${escapeHtml(fmt(total))}</strong></div>
    </div>
    <div class="footer">
      <div class="sign">Отпустил</div>
      <div class="sign">Принял</div>
    </div>
    <div class="note">Курьерский чек / печать из панели доставки</div>
  </div>
</body>
</html>`;
};

function ReceiptPreview({ order, onPrint }: { order: any; onPrint: () => void }) {
  return (
    <View style={st.receiptCard}>
      <View style={st.receiptBrandRow}>
        <Image source={zarramarketLogo} style={st.receiptLogo} contentFit="contain" />
        <View style={{ flex: 1 }}>
          <Text style={st.receiptTitle}>ZarraMarket</Text>
          <Text style={st.receiptMeta}>{order.number} • {orderDateLabel(order.created_at)}</Text>
        </View>
      </View>
      <View style={st.receiptMetaGrid}>
        <View style={{ flex: 1 }}>
          <Text style={st.receiptMetaLine}><Text style={st.receiptMetaLabel}>Mijoz:</Text> {order.client_name}</Text>
          <Text style={st.receiptMetaLine}><Text style={st.receiptMetaLabel}>Tel:</Text> {order.client_phone}</Text>
          <Text style={st.receiptMetaLine}><Text style={st.receiptMetaLabel}>Manzil:</Text> {order.address_text}</Text>
        </View>
        <View style={{ flex: 1 }}>
          <Text style={st.receiptMetaLine}><Text style={st.receiptMetaLabel}>Sotuvchi:</Text> {RECEIPT_SELLER_NAME}</Text>
          <Text style={st.receiptMetaLine}><Text style={st.receiptMetaLabel}>Holat:</Text> Kuryer cheki</Text>
        </View>
      </View>
      <View style={st.receiptTable}>
        <View style={[st.receiptRow, st.receiptHeadRow]}>
          <Text style={[st.receiptCell, st.receiptIdx]}>№</Text>
          <Text style={[st.receiptCell, st.receiptName]}>Nomi</Text>
          <Text style={[st.receiptCell, st.receiptPrice]}>1 narx</Text>
          <Text style={[st.receiptCell, st.receiptQty]}>Ichida</Text>
          <Text style={[st.receiptCell, st.receiptPrice]}>1 dona</Text>
          <Text style={[st.receiptCell, st.receiptQty]}>Soni</Text>
          <Text style={[st.receiptCell, st.receiptSum]}>Jami</Text>
        </View>
        {(order.items || []).map((item: any, idx: number) => {
          const lineTotal = Number(item.qty || 0) * Number(item.price || 0);
          return (
            <View key={`${item.item_id || item.product_id || idx}-receipt`} style={st.receiptRow}>
              <Text style={[st.receiptCell, st.receiptIdx]}>{idx + 1}</Text>
              <Text style={[st.receiptCell, st.receiptName]} numberOfLines={2}>{item.name?.uz || item.name || "Mahsulot"}{item.variation ? ` • ${item.variation}` : ""}</Text>
              <Text style={[st.receiptCell, st.receiptPrice]}>{fmt(item.price || 0)}</Text>
              <Text style={[st.receiptCell, st.receiptQty]}>{itemUnitContents(item)}</Text>
              <Text style={[st.receiptCell, st.receiptPrice]}>{fmt(itemPiecePrice(item))}</Text>
              <Text style={[st.receiptCell, st.receiptQty]}>{item.qty}</Text>
              <Text style={[st.receiptCell, st.receiptSum]}>{fmt(lineTotal)}</Text>
            </View>
          );
        })}
      </View>
      <View style={st.receiptSummaryBox}>
        <View style={st.receiptSummaryRow}><Text style={st.receiptSummaryLabel}>Tovarlar</Text><Text style={st.receiptSummaryValue}>{fmt(order.subtotal || 0)}</Text></View>
        <View style={st.receiptSummaryRow}><Text style={st.receiptSummaryLabel}>Yetkazib berish</Text><Text style={st.receiptSummaryValue}>{fmt(order.delivery_fee || 0)}</Text></View>
        <View style={st.receiptSummaryRow}><Text style={st.receiptSummaryLabel}>Chegirma</Text><Text style={st.receiptSummaryValue}>{fmt(order.discount || 0)}</Text></View>
        <View style={[st.receiptSummaryRow, st.receiptSummaryRowTotal]}><Text style={st.receiptSummaryTotalLabel}>Jami</Text><Text style={st.receiptSummaryTotalValue}>{fmt(order.total || 0)}</Text></View>
      </View>
      <View style={st.receiptFooterRow}>
        <Text style={st.receiptFooterLine}>Topshirdi</Text>
        <Text style={st.receiptFooterLine}>Qabul qildi</Text>
      </View>
      <Pressable testID={`courier-print-${order.id}`} style={st.printBtn} onPress={onPrint}>
        <Ionicons name="print-outline" size={16} color="#fff" />
        <Text style={st.printBtnTxt}>Chekni print qilish</Text>
      </Pressable>
    </View>
  );
}

export default function Courier() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { logout, user } = useAuth();
  const isHub = isAdminCourierUser(user);
  const [stats, setStats] = useState<any>(null);
  const [available, setAvailable] = useState<any[]>([]);
  const [released, setReleased] = useState<any[]>([]);
  const [mine, setMine] = useState<any[]>([]);
  const [online, setOnline] = useState(false);
  const [confirmLogout, setConfirmLogout] = useState(false);
  const [finalizingOrder, setFinalizingOrder] = useState<any | null>(null);
  const [finalizeMap, setFinalizeMap] = useState<FinalizeMap>({});
  const [savingFinalize, setSavingFinalize] = useState(false);
  const [finalizeError, setFinalizeError] = useState("");
  const [hubBusy, setHubBusy] = useState<string | null>(null);

  const load = useCallback(() => {
    api("/courier/stats").then((s) => { setStats(s); setOnline(!!s?.online); }).catch(() => {});
    if (isHub) {
      api("/courier/hub-queue")
        .then((data) => {
          setAvailable(data?.waiting || []);
          setReleased(data?.released || []);
        })
        .catch(() => {
          api("/courier/available").then(setAvailable).catch(() => {});
        });
      setMine([]);
    } else {
      api("/courier/available").then(setAvailable).catch(() => {});
      api("/courier/my").then(setMine).catch(() => {});
      setReleased([]);
    }
  }, [isHub]);

  useFocusEffect(useCallback(() => {
    load();
    const iv = setInterval(load, 15000);
    return () => clearInterval(iv);
  }, [load]));

  const toggle = async (v: boolean) => {
    setOnline(v);
    await api("/courier/toggle", { method: "POST", body: { online: v } }).catch(() => {});
    if (v) {
      // Send an immediate GPS ping the moment the courier goes online, so
      // the admin map isn't stuck on a stale/registration-time location.
      getCurrentLocation()
        .then((loc) => api("/users/me/location", { method: "PUT", body: loc }))
        .catch(() => {});
    }
  };

  // While online, periodically report GPS position so the admin's live map
  // shows where each courier actually is right now, not just at signup.
  useEffect(() => {
    if (!online) return;
    const report = () => {
      getCurrentLocation()
        .then((loc) => api("/users/me/location", { method: "PUT", body: loc }))
        .catch(() => {});
    };
    report();
    const iv = setInterval(report, 30000);
    return () => clearInterval(iv);
  }, [online]);

  const accept = async (oid: string) => {
    try {
      await api(`/courier/orders/${oid}/accept`, { method: "POST" });
    } catch (e: any) {
      Alert.alert("Xatolik", e?.message || "Qabul qilib bo'lmadi");
    }
    load();
  };

  const hubCheck = async (order: any) => {
    if (!order?.id) return;
    setHubBusy(order.id);
    try {
      await api(`/courier/orders/${order.id}/hub-check`, { method: "POST" });
      // Chekni darhol ochish — admin kuryer vazifasi
      printReceipt(order);
      load();
    } catch (e: any) {
      Alert.alert("Xatolik", e?.message || "Hub-check muvaffaqiyatsiz");
    } finally {
      setHubBusy(null);
    }
  };

  const cancelTakenOrder = async (oid: string) => {
    try {
      const ok =
        Platform.OS === "web"
          ? typeof window !== "undefined"
            ? window.confirm(
                "Buyurtmani bekor qilmoqchimisiz? Statistika yangilanadi, boshqa kuryer olishi mumkin bo'ladi."
              )
            : true
          : await new Promise<boolean>((resolve) => {
              Alert.alert(
                "Tasdiqlash",
                "Buyurtmani bekor qilmoqchimisiz? Statistika yangilanadi.",
                [
                  { text: "Yo'q", style: "cancel", onPress: () => resolve(false) },
                  { text: "Ha", style: "destructive", onPress: () => resolve(true) },
                ],
                { cancelable: true }
              );
            });
      if (!ok) return;
      await api(`/courier/orders/${oid}/cancel`, { method: "POST" });
      await load();
      if (Platform.OS === "web" && typeof window !== "undefined") {
        // web: minor feedback
      }
    } catch (e: any) {
      const msg = e?.message || "Bekor qilib bo'lmadi";
      if (Platform.OS === "web") {
        if (typeof window !== "undefined") window.alert(msg);
      } else {
        Alert.alert("Xatolik", msg);
      }
    }
  };

  const openFinalizeModal = (order: any) => {
    const initial: FinalizeMap = {};
    (order.items || []).forEach((item: any, idx: number) => {
      initial[idx] = item.delivery_status === "returned" ? "returned" : "delivered";
    });
    setFinalizeMap(initial);
    setFinalizeError("");
    setFinalizingOrder(order);
  };

  const closeFinalizeModal = () => {
    if (savingFinalize) return;
    setFinalizingOrder(null);
    setFinalizeMap({});
    setFinalizeError("");
  };

  const toggleItemReturn = (idx: number) => {
    setFinalizeMap((prev) => ({
      ...prev,
      [idx]: prev[idx] === "returned" ? "delivered" : "returned",
    }));
  };

  const submitFinalize = async (forceAllDelivered = false) => {
    if (!finalizingOrder) return;
    const items = (finalizingOrder.items || []).map((_: any, idx: number) => ({
      index: idx,
      action: forceAllDelivered ? "delivered" : (finalizeMap[idx] || "delivered"),
    }));

    setSavingFinalize(true);
    setFinalizeError("");
    try {
      await api(`/courier/orders/${finalizingOrder.id}/complete`, { method: "POST", body: { items } });
      setSavingFinalize(false);
      setFinalizingOrder(null);
      setFinalizeMap({});
      setFinalizeError("");
      load();
      return;
    } catch (e: any) {
      setFinalizeError(e.message || "Saqlashda xatolik yuz berdi");
    }
    setSavingFinalize(false);
  };

  const active = mine.filter((o) => o.status === "courier");

  const printReceipt = (order: any) => {
    if (Platform.OS !== "web" || typeof window === "undefined") return;
    const printWindow = window.open("", "_blank", "width=920,height=1100");
    if (!printWindow) return;
    printWindow.document.open();
    printWindow.document.write(buildReceiptHtml(order));
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
    }, 300);
  };

  const openRoute = (o: any) => router.push(`/courier-map/${o.id}`);
  const openShop = (o: any) => Linking.openURL(pointUrl({ lat: o.shop_lat, lng: o.shop_lng }));
  const openDest = (o: any) => Linking.openURL(pointUrl({ lat: o.address_lat, lng: o.address_lng }));

  const finalizeCounts = useMemo(() => {
    const items = finalizingOrder?.items || [];
    let delivered = 0;
    let returned = 0;
    items.forEach((_: any, idx: number) => {
      if ((finalizeMap[idx] || "delivered") === "returned") returned += 1;
      else delivered += 1;
    });
    return { delivered, returned };
  }, [finalizeMap, finalizingOrder]);

  const ItemLines = ({ items, compact = false }: { items: any[]; compact?: boolean }) => (
    <View style={{ marginTop: S.sm, gap: 6 }}>
      {items.map((item: any, idx: number) => (
        <View key={`${item.item_id || item.product_id || idx}-${idx}`} style={[st.itemLine, compact && { paddingVertical: 6 }]}> 
          <View style={{ flex: 1 }}>
            <Text style={st.itemName} numberOfLines={2}>{item.name?.uz || item.name || "Mahsulot"}{item.variation ? ` • ${item.variation}` : ""}</Text>
            <Text style={st.itemMeta}>{item.qty} × {fmt(item.price || 0)}</Text>
          </View>
          {item.delivery_status === "returned" && (
            <View style={st.returnBadge}>
              <Text style={st.returnBadgeTxt}>Qaytgan</Text>
            </View>
          )}
        </View>
      ))}
    </View>
  );

  return (
    <View style={[st.root, { paddingTop: insets.top }]}> 
      <LinearGradient colors={[C.inverse, "#064E3B"]} style={st.header}>
        <Pressable testID="courier-logout-button" onPress={() => setConfirmLogout(true)} style={st.backBtn}>
          <Ionicons name="log-out-outline" size={20} color="#fff" />
        </Pressable>
        <Text style={st.headerTitle}>{isHub ? "Admin kuryer (hub)" : "Kuryer rejimi"}</Text>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <Text style={{ color: online ? C.brand : "rgba(255,255,255,0.5)", fontWeight: "800", fontSize: 12 }}>{online ? "Onlayn" : "Offlayn"}</Text>
          <Switch testID="courier-online-toggle" value={online} onValueChange={toggle} trackColor={{ true: C.brand, false: "#4B5563" }} thumbColor="#fff" />
        </View>
      </LinearGradient>

      {confirmLogout && (
        <View style={st.confirmBar}>
          <Text style={st.confirmTxt}>Hisobdan chiqmoqchimisiz?</Text>
          <View style={{ flexDirection: "row", gap: S.sm }}>
            <Pressable testID="courier-logout-confirm" style={[st.miniBtn, { backgroundColor: C.error }]} onPress={logout}>
              <Text style={st.miniBtnTxt}>Ha, chiqish</Text>
            </Pressable>
            <Pressable testID="courier-logout-cancel" style={[st.miniBtn, { backgroundColor: C.tertiary }]} onPress={() => setConfirmLogout(false)}>
              <Text style={[st.miniBtnTxt, { color: C.onSurface }]}>Bekor qilish</Text>
            </Pressable>
          </View>
        </View>
      )}

      <ScrollView contentContainerStyle={{ padding: S.lg, maxWidth: 800, width: "100%", alignSelf: "center", paddingBottom: S.xxl }}>
        {stats && (
          <>
            <View style={st.statRow}>
              <View style={st.statCard}>
                <Text style={st.statVal}>{stats.active_count || 0}</Text>
                <Text style={st.statLabel}>Aktiv buyurtmalar</Text>
              </View>
              <View style={st.statCard}>
                <Text style={st.statVal}>{fmt(stats.active_total || 0)}</Text>
                <Text style={st.statLabel}>Aktiv buyurtmalar summasi</Text>
              </View>
              <View style={st.statCard}>
                <Text style={st.statVal}>{stats.today_taken_count || 0}</Text>
                <Text style={st.statLabel}>Bugun olingan buyurtmalar</Text>
              </View>
            </View>

            <View style={[st.statRow, { marginTop: S.md }]}> 
              <View style={st.statCard}>
                <Text style={st.statVal}>{fmt(stats.today_taken_total || 0)}</Text>
                <Text style={st.statLabel}>Bugun olingan summasi</Text>
              </View>
              <View style={st.statCard}>
                <Text style={st.statVal}>{stats.today_deliveries || 0}</Text>
                <Text style={st.statLabel}>Bugun yetkazildi</Text>
              </View>
              <View style={st.statCard}>
                <Text style={st.statVal}>{fmt(stats.earnings || 0)}</Text>
                <Text style={st.statLabel}>Jami daromad</Text>
              </View>
            </View>
          </>
        )}
        {stats?.zone && <Text style={st.zone}>📍 Zona: {stats.zone}</Text>}
        {stats?.stats_reset_at && <Text style={st.resetInfo}>Statistika admin tomonidan yangilangan: {new Date(stats.stats_reset_at).toLocaleString()}</Text>}

        {!isHub && <Text style={st.secTitle}>Aktiv yetkazishlarim ({active.length})</Text>}
        {!isHub && active.length === 0 && <Text style={st.empty}>Aktiv yetkazish yo'q</Text>}
        {!isHub && active.map((o) => (
          <View key={o.id} style={[st.card, { borderColor: C.brandDark, borderWidth: 1.5 }]}>
            <Text style={st.orderNum}>{o.number} • {fmt(o.total)}</Text>
            <View style={st.routeRow}>
              <View style={st.routeDot} />
              <Text style={st.meta}>A: {o.shop_name} (do'kondan olish)</Text>
              <Pressable testID={`courier-open-pickup-${o.id}`} style={st.mapMini} onPress={() => openShop(o)}>
                <Ionicons name="map" size={12} color={C.brandDark} />
                <Text style={st.mapMiniTxt}>Xaritada</Text>
              </Pressable>
            </View>
            <View style={st.routeRow}>
              <View style={[st.routeDot, { backgroundColor: C.error }]} />
              <Text style={st.meta}>B: {o.address_text}</Text>
              <Pressable testID={`courier-open-delivery-${o.id}`} style={st.mapMini} onPress={() => openDest(o)}>
                <Ionicons name="map" size={12} color={C.error} />
                <Text style={[st.mapMiniTxt, { color: C.error }]}>Xaritada</Text>
              </Pressable>
            </View>
            {o.location_approx && <Text style={st.approxTxt}>⚠️ Yetkazish nuqtasi taxminiy (haridor GPS kiritmagan)</Text>}
            <Text style={st.meta}>👤 {o.client_name} • {o.client_phone}</Text>
            <Text style={st.itemHeader}>Mahsulotlar</Text>
            <ItemLines items={o.items || []} compact />
            <ReceiptPreview order={o} onPrint={() => printReceipt(o)} />
            {!!o.delivery_eta_days && <Text style={st.resetInfo}>Taxminiy yetib borish: {o.delivery_eta_days} kun</Text>}
            {!!o.can_cancel_courier && <Text style={st.resetInfo}>Bekor qilish mumkin: {o.courier_cancel_deadline ? new Date(o.courier_cancel_deadline).toLocaleString() : "1 soat ichida"}</Text>}
            <View style={{ flexDirection: "row", gap: S.sm, marginTop: S.md, flexWrap: "wrap" }}>
              <Pressable testID={`courier-map-${o.id}`} style={[st.btn, { flex: 1, backgroundColor: C.inverse, flexDirection: "row", justifyContent: "center", gap: 6 }]} onPress={() => openRoute(o)}>
                <Ionicons name="navigate" size={16} color="#fff" />
                <Text style={st.btnTxt}>Marshrut A→B</Text>
              </Pressable>
              <Pressable testID={`courier-delivered-${o.id}`} style={[st.btn, { flex: 1, backgroundColor: C.success }]} onPress={() => openFinalizeModal(o)}>
                <Text style={st.btnTxt}>Yetkazdim ✓</Text>
              </Pressable>
              {o.can_cancel_courier && (
                <Pressable
                  testID={`courier-cancel-${o.id}`}
                  style={[st.btn, { flexBasis: "100%", backgroundColor: C.error }]}
                  onPress={() => cancelTakenOrder(o.id)}
                >
                  <Text style={st.btnTxt}>Qabulni bekor qilish</Text>
                </Pressable>
              )}
            </View>
          </View>
        ))}

        {isHub ? (
          <>
            <Text style={st.secTitle}>Hub navbati — tekshirish kerak ({available.length})</Text>
            <Text style={st.empty}>Barcha buyurtmalar avval shu yerda. Chek chiqaring, keyin oddiy kuryerlarga ochiladi.</Text>
            {available.length === 0 && <Text style={[st.empty, { marginTop: 8 }]}>Hozircha kutayotgan buyurtma yo'q</Text>}
            {available.map((o, i) => (
              <Animated.View key={o.id} entering={FadeInDown.delay(i * 80).springify()} style={st.card}>
                <Text style={st.orderNum}>{o.number} • {fmt(o.total)}</Text>
                <View style={st.routeRow}>
                  <View style={st.routeDot} />
                  <Text style={st.meta}>A: {o.shop_name} (sotuvchi)</Text>
                </View>
                <View style={st.routeRow}>
                  <View style={[st.routeDot, { backgroundColor: C.error }]} />
                  <Text style={st.meta}>B: {o.address_text}</Text>
                </View>
                <Text style={st.meta}>👤 {o.client_name} • {o.client_phone}</Text>
                <Text style={st.itemHeader}>Mahsulotlar</Text>
                <ItemLines items={o.items || []} compact />
                <ReceiptPreview order={o} onPrint={() => printReceipt(o)} />
                <View style={{ flexDirection: "row", gap: S.sm, marginTop: S.md, flexWrap: "wrap" }}>
                  <Pressable
                    testID={`admin-courier-hub-check-${o.id}`}
                    disabled={hubBusy === o.id}
                    style={[st.btn, { flex: 1, backgroundColor: C.success, opacity: hubBusy === o.id ? 0.6 : 1 }]}
                    onPress={() => hubCheck(o)}
                  >
                    <Text style={st.btnTxt}>{hubBusy === o.id ? "Kutilmoqda..." : "Qabul + chek + kuryerga"}</Text>
                  </Pressable>
                </View>
              </Animated.View>
            ))}

            <Text style={st.secTitle}>Kuryerlarga chiqarilgan ({released.length})</Text>
            {released.length === 0 && <Text style={st.empty}>Hali chiqarilgan buyurtma yo'q</Text>}
            {released.map((o) => (
              <View key={o.id} style={[st.card, { opacity: 0.95 }]}>
                <Text style={st.orderNum}>{o.number} • {fmt(o.total)}</Text>
                <Text style={st.meta}>B: {o.address_text}</Text>
                <Text style={[st.meta, { color: C.success, fontWeight: "800" }]}>
                  ✓ Hub-check: {o.admin_courier_checked_at ? new Date(o.admin_courier_checked_at).toLocaleString() : "—"}
                </Text>
                <Text style={st.meta}>Oddiy kuryer hali olmagan — kutilyapti</Text>
                <ReceiptPreview order={o} onPrint={() => printReceipt(o)} />
              </View>
            ))}
          </>
        ) : (
          <>
            <Text style={st.secTitle}>Yangi takliflar ({available.length})</Text>
            {!online && <Text style={st.empty}>Takliflarni ko'rish uchun Onlayn rejimga o'ting</Text>}
            {online && available.length === 0 && <Text style={st.empty}>Hozircha yangi taklif yo'q (admin kuryer chek chiqargach chiqadi)</Text>}
            {online && available.map((o, i) => (
              <Animated.View key={o.id} entering={FadeInDown.delay(i * 80).springify()} style={st.card}>
                <Text style={st.orderNum}>{o.number}</Text>
                <View style={st.routeRow}>
                  <View style={st.routeDot} />
                  <Text style={st.meta}>A: {o.shop_name} (sotuvchi)</Text>
                  <Pressable testID={`courier-open-pickup-${o.id}`} style={st.mapMini} onPress={() => openShop(o)}>
                    <Ionicons name="map" size={12} color={C.brandDark} />
                    <Text style={st.mapMiniTxt}>Xaritada</Text>
                  </Pressable>
                </View>
                <View style={st.routeRow}>
                  <View style={[st.routeDot, { backgroundColor: C.error }]} />
                  <Text style={st.meta}>B: {o.address_text}</Text>
                  <Pressable testID={`courier-open-delivery-${o.id}`} style={st.mapMini} onPress={() => openDest(o)}>
                    <Ionicons name="map" size={12} color={C.error} />
                    <Text style={[st.mapMiniTxt, { color: C.error }]}>Xaritada</Text>
                  </Pressable>
                </View>
                {o.location_approx && <Text style={st.approxTxt}>⚠️ Yetkazish nuqtasi taxminiy (haridor GPS kiritmagan)</Text>}
                <Text style={st.itemHeader}>Buyurtma ichidagi mahsulotlar</Text>
                <ItemLines items={o.items || []} compact />
                <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginTop: S.sm, gap: S.sm }}>
                  <Text style={{ fontWeight: "900", color: C.brandDark }}>Haq: {fmt(o.delivery_fee || 15000)}</Text>
                  <View style={{ flexDirection: "row", gap: S.sm }}>
                    <Pressable testID={`courier-map-preview-${o.id}`} style={st.iconBtn} onPress={() => openRoute(o)}>
                      <Ionicons name="navigate-outline" size={17} color={C.onSurface} />
                    </Pressable>
                    <Pressable testID={`courier-accept-${o.id}`} style={st.btn} onPress={() => accept(o.id)}>
                      <Text style={st.btnTxt}>Qabul qilish</Text>
                    </Pressable>
                  </View>
                </View>
              </Animated.View>
            ))}
          </>
        )}

        {!isHub && <Text style={st.secTitle}>Tarix</Text>}
        {!isHub && mine.filter((o) => o.status === "delivered").length === 0 && <Text style={st.empty}>Hali yetkazishlar yo'q</Text>}
        {!isHub && mine.filter((o) => o.status === "delivered").map((o) => (
          <View key={o.id} style={[st.card, { opacity: 0.92 }]}> 
            <View style={{ flexDirection: "row", justifyContent: "space-between", gap: S.sm }}>
              <Text style={st.orderNum}>{o.number}</Text>
              <Text style={{ color: C.success, fontWeight: "800", fontSize: 12 }}>✓ Yetkazildi</Text>
            </View>
            <Text style={st.meta}>{o.address_text}</Text>
            {!!o.returned_items_count && <Text style={st.returnSummary}>Qaytgan mahsulotlar: {o.returned_items_count} ta</Text>}
            <ItemLines items={o.items || []} compact />
            <Text style={[st.meta, { fontWeight: "800", color: C.brandDark }]}>Yakuniy buyurtma summasi: {fmt(o.total || 0)}</Text>
          </View>
        ))}
      </ScrollView>

      <Modal visible={!!finalizingOrder} transparent animationType="slide" onRequestClose={closeFinalizeModal}>
        <View style={st.modalBackdrop}>
          <View style={st.modalCard}>
            <View style={st.modalHeader}>
              <View style={{ flex: 1 }}>
                <Text style={st.modalTitle}>Yetkazilgan mahsulotlar</Text>
                <Text style={st.modalSub}>{finalizingOrder?.number}</Text>
              </View>
              <Pressable onPress={closeFinalizeModal} style={st.closeBtn}>
                <Ionicons name="close" size={18} color={C.onSurface} />
              </Pressable>
            </View>

            <ScrollView style={{ maxHeight: 340 }} contentContainerStyle={{ gap: 8, paddingBottom: 6 }}>
              {(finalizingOrder?.items || []).map((item: any, idx: number) => {
                const returned = (finalizeMap[idx] || "delivered") === "returned";
                return (
                  <View key={`${item.item_id || item.product_id || idx}-${idx}`} style={st.modalItemRow}>
                    <View style={{ flex: 1 }}>
                      <Text style={st.modalItemName}>{item.name?.uz || item.name || "Mahsulot"}{item.variation ? ` • ${item.variation}` : ""}</Text>
                      <Text style={st.modalItemMeta}>{item.qty} × {fmt(item.price || 0)}</Text>
                    </View>
                    <Pressable onPress={() => toggleItemReturn(idx)} style={[st.toggleReturnBtn, returned && st.toggleReturnBtnActive]}>
                      <Ionicons name={returned ? "close" : "checkmark"} size={16} color={returned ? "#fff" : C.success} />
                      <Text style={[st.toggleReturnTxt, returned && { color: "#fff" }]}>{returned ? "Qaytariladi" : "Oldi"}</Text>
                    </Pressable>
                  </View>
                );
              })}
            </ScrollView>

            <View style={st.modalSummary}>
              <Text style={st.modalSummaryTxt}>Yetkaziladi: {finalizeCounts.delivered} ta</Text>
              <Text style={[st.modalSummaryTxt, finalizeCounts.returned > 0 && { color: C.error }]}>Qaytadi: {finalizeCounts.returned} ta</Text>
            </View>
            {!!finalizeError && <Text style={st.finalizeError}>{finalizeError}</Text>}

            <View style={{ gap: S.sm, marginTop: S.md }}>
              <Pressable disabled={savingFinalize} style={[st.primaryModalBtn, savingFinalize && { opacity: 0.6 }]} onPress={() => submitFinalize(true)}>
                <Text style={st.primaryModalBtnTxt}>Hammasini oldi</Text>
              </Pressable>
              <Pressable disabled={savingFinalize} style={[st.secondaryModalBtn, savingFinalize && { opacity: 0.6 }]} onPress={() => submitFinalize(false)}>
                <Text style={st.secondaryModalBtnTxt}>Tanlangan holatni saqlash</Text>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

